/* Rescate: recuperar datos de discos danados, borrados o formateados */
#include "z.h"
typedef struct { char name[16], mnt[16], fs[8], label[16]; u64 start, sectors; u32 ss; int disk, root; } src_t;
typedef struct { char name[16], fs[8], label[16], dev[16]; u64 free_b; } dst_t;
static zwin *W; static src_t S[48]; static int ns, cs = -1; static dst_t D[24]; static int nd, cd = -1; static int tab; static char msg[200], sub[200]; static int pct = -1, busy, cancel; static u64 lastui;
static const char *TABS[] = {"Copiar archivos", "Borrados", "Recuperacion profunda", "Imagen de disco", "Particiones"};
#define LW 230
#define TB 36
static char outdir[300]; static int logf_ = -1; static char path_[256] = "/"; static int pfoc, pcur = 1; static int cats = 1;
static void root_of(const char *d, char *o) { strncpy0(o, d, 16); char *p = strrchr(o, 'p'); if (p && p > o && isdigit(p[1]) && isdigit(p[-1])) *p = 0; }
static void scan_devs(void) {
    zdisk dk[16]; int n = z_disks(dk, 16); zmount m[32]; int nm = z_mounts(m, 32); char old[16] = ""; if (cs >= 0 && cs < ns) strcpy(old, S[cs].name); ns = 0; char sysd[16]; dk_sys_disk(sysd);
    for (int i = 0; i < n && ns < 48; i++) { src_t *s = &S[ns]; memset(s, 0, sizeof *s); strcpy(s->name, dk[i].name); s->sectors = dk[i].sectors; s->ss = dk[i].ssize; s->disk = 1; s->root = i; ns++; for (int k = 0; k < nm; k++) if (!strcmp(m[k].dev, dk[i].name)) { strcpy(S[ns - 1].mnt, m[k].name); strcpy(S[ns - 1].fs, m[k].fstype); strcpy(S[ns - 1].label, m[k].label); }
        zpart p[16]; int np = z_parts(dk[i].name, p, 16); for (int j = 0; j < np && ns < 48; j++) { s = &S[ns++]; memset(s, 0, sizeof *s); strcpy(s->name, p[j].name); s->start = p[j].start; s->sectors = p[j].sectors; s->ss = dk[i].ssize; s->root = i; strcpy(s->fs, "?"); for (int k = 0; k < nm; k++) if (!strcmp(m[k].dev, p[j].name)) { strcpy(s->mnt, m[k].name); strcpy(s->fs, m[k].fstype); strcpy(s->label, m[k].label); } } }
    cs = -1; for (int i = 0; i < ns; i++) if (!strcmp(S[i].name, old)) cs = i;
    char sr[16] = ""; if (cs >= 0) root_of(S[cs].name, sr); char od[16] = ""; if (cd >= 0 && cd < nd) strcpy(od, D[cd].name); nd = 0; cd = -1;
    for (int k = 0; k < nm && nd < 24; k++) { if (strncmp(m[k].fstype, "fat", 3)) continue; char r[16]; root_of(m[k].dev, r); if (sr[0] && !strcmp(r, sr)) continue; dst_t *d = &D[nd]; strcpy(d->name, m[k].name); strcpy(d->fs, m[k].fstype); strcpy(d->label, m[k].label); strcpy(d->dev, m[k].dev); d->free_b = m[k].free_b; if (!strcmp(d->name, od)) cd = nd; nd++; } if (cd < 0 && nd) cd = 0;
}
static void hum(u64 z, char *s) { if (z >> 40) snprintf(s, 24, "%lu.%lu TB", z >> 40, ((z >> 30) & 1023) * 10 / 1024); else if (z >> 30) snprintf(s, 24, "%lu.%lu GB", z >> 30, ((z >> 20) & 1023) * 10 / 1024); else if (z >> 20) snprintf(s, 24, "%lu MB", z >> 20); else snprintf(s, 24, "%lu KB", z >> 10); }
/* lista de borrados */
typedef struct { char *path; u64 size, a, b; int ok, sel, ntfs; } del_t; static del_t *DL; static int ndl, dtop;
static int ptop; typedef struct { u64 lba, n; char kind[8], lab[16]; int sel; } lost_t; static lost_t LP[64]; static int nlp;
static const char *CN[] = {"Todo", "Documentos", "Fotos", "Audio y video"};
static int tc[8]; static const char *TN[] = {"Fotos", "Documentos", "Audio y video", "Comprimidos"}; static int tsel = 15;
static void draw(void);
static void tick(int force) { u64 t = z_ms(); if (!force && t - lastui < 150) return; lastui = t; zevent e; while (z_event(&e, 0)) if (e.win == (u32)W->id && ((e.type == EV_DOWN && e.y >= W->h - 42 && e.x >= W->w - 110) || (e.type == EV_KEY && e.ch == 27))) cancel = 1; draw(); }
static void P_(int p, const char *f, ...) { pct = p; va_list a; va_start(a, f); vsnprintf(msg, 200, f, a); va_end(a); tick(0); }
static void row(int x, int y, int w, const char *a, const char *b, int on) { if (on) g_rect(W, x, y, w, 36, UI_ACC2); zw_clip(W, x + 6, y, w - 8, 36); g_text(W, x + 6, y + 2, a, UI_TEXT); g_text(W, x + 6, y + 18, b, UI_MUTED); zw_noclip(W); }
static void draw(void) {
    g_clear(W, UI_BG); g_rect(W, 0, 0, W->w, TB, 0x7F1D1D); int x = 6; for (int i = 0; i < 5; i++) { int w = g_textw(TABS[i]) + 14; ui_button(W, x, 5, w, 26, TABS[i], tab == i ? 2 : 0); x += w + 4; } g_rect(W, 0, TB, LW, W->h - TB, UI_PANEL); g_textb(W, 8, TB + 5, "Origen (solo lectura)", 0x7F1D1D); char a[24], b[80]; int y = TB + 24;
    for (int i = 0; i < ns && y < W->h - 170; i++) { hum(S[i].sectors * S[i].ss, a); snprintf(b, 80, "%s%s %s", S[i].mnt[0] ? S[i].fs : S[i].disk ? _("disco") : _("sin montar"), "", S[i].label); char c[40]; snprintf(c, 40, "%s%s  %s", S[i].disk ? "" : "  ", S[i].name, a); row(0, y, LW, c, b, i == cs); y += 36; }
    y = W->h - 150; g_rect(W, 0, y - 4, LW, 1, UI_LINE); g_textb(W, 8, y, "Destino (otro disco)", 0x166534); y += 20; for (int i = 0; i < nd && i < 3; i++) { hum(D[i].free_b, a); snprintf(b, 80, _("%s libres"), a); char c[40]; snprintf(c, 40, "/%s %s", D[i].name, D[i].label); row(0, y, LW, c, b, i == cd); y += 36; } if (!nd) g_text(W, 8, y, "Conecta otro disco", 0xB91C1C);
    int X = LW + 14, Y = TB + 10, wd = W->w - X - 12;
    if (tab == 0) { g_textb(W, X, Y, "Copiar archivos de un volumen legible", UI_TEXT); Y += 22; g_text(W, X, Y, "Si hay sectores danados los salta y sigue. Anota todo en RESCATE.TXT.", UI_MUTED); Y += 28; g_text(W, X, Y + 5, "Carpeta", UI_TEXT); ui_input(W, X + 70, Y, wd - 70, 26, path_, pcur, pfoc); Y += 36; for (int i = 0; i < 4; i++) ui_button(W, X + i * 124, Y, 120, 26, CN[i], cats == 1 << i ? 2 : 0); }
    else if (tab == 1) { g_textb(W, X, Y, "Archivos borrados (FAT, NTFS, exFAT y ext)", UI_TEXT); ui_button(W, W->w - 106, Y - 4, 94, 26, "Todos", 0); Y += 24; int vh = (W->h - 60 - Y) / 20; for (int i = dtop; i < ndl && i < dtop + vh; i++) { int ry = Y + (i - dtop) * 20; del_t *d = &DL[i]; if (d->sel) g_rect(W, X, ry, wd, 20, UI_ACC2); g_frame(W, X + 3, ry + 4, 11, 11, UI_MUTED); if (d->sel) g_rect(W, X + 5, ry + 6, 7, 7, UI_ACC); hum(d->size, a); g_rect(W, X + wd - 110, ry + 5, 9, 9, d->ok ? 0x16A34A : 0xD97706); g_text(W, X + wd - 96, ry + 2, a, UI_MUTED); zw_clip(W, X + 18, ry, wd - 134, 20); g_text(W, X + 20, ry + 2, d->path, UI_TEXT); zw_noclip(W); } if (!ndl) g_text(W, X, Y, "Elige una particion y pulsa Buscar.", UI_MUTED); }
    else if (tab == 2) { g_textb(W, X, Y, "Recuperacion profunda por firmas", UI_TEXT); Y += 22; g_text(W, X, Y, "Lee todo el disco buscando archivos. Sirve tras formatear o", UI_MUTED); g_text(W, X, Y + 16, "si el sistema de archivos esta destruido. No recupera nombres.", UI_MUTED); Y += 44; for (int i = 0; i < 4; i++) ui_button(W, X + i * 124, Y, 120, 26, TN[i], tsel & 1 << i ? 2 : 0); Y += 40; snprintf(b, 80, _("Encontrados: %d fotos, %d documentos, %d audio/video, %d zip"), tc[0], tc[1], tc[2], tc[3]); g_text(W, X, Y, b, UI_TEXT); }
    else if (tab == 3) { g_textb(W, X, Y, "Imagen completa del disco o particion", UI_TEXT); Y += 22; g_text(W, X, Y, "Copia sector a sector en trozos de 2 GB. Los sectores ilegibles se", UI_MUTED); g_text(W, X, Y + 16, "rellenan con ceros y se anotan en el archivo .MAP.", UI_MUTED); }
    else { g_textb(W, X, Y, "Particiones perdidas", UI_TEXT); Y += 22; g_text(W, X, Y, "Busca sistemas de archivos aunque la tabla este borrada. Pulsa uno para montarlo.", UI_MUTED); Y += 24; for (int i = ptop; i < nlp && i < 10; i++) { char c[100]; hum(LP[i].n * 512, a); snprintf(c, 100, _("%s  inicio %lu  %s  %s"), LP[i].kind, LP[i].lba, a, LP[i].lab); ui_button(W, X, Y, wd, 26, c, 0); Y += 30; } }
    static const char *act[] = {"Copiar", "Buscar", "Empezar", "Crear imagen", "Buscar"}; int by = W->h - 42; if (pct >= 0) { g_rect(W, X, by - 38, wd, 10, UI_LINE); g_rect(W, X, by - 38, wd * pct / 100, 10, 0xB91C1C); } zw_clip(W, X, by - 26, wd, 60); g_text(W, X, by - 24, msg, UI_TEXT); g_text(W, X, by - 6 + 0, sub, UI_MUTED); zw_noclip(W); if (busy) ui_button(W, W->w - 100, by + 6, 88, 28, "Cancelar", 0); else { ui_button(W, W->w - 124, by + 6, 112, 28, act[tab], 2); if (tab == 1 && ndl) ui_button(W, W->w - 250, by + 6, 118, 28, "Recuperar", 2); } zw_present(W);
}
/* --- utilidades --- */
static void mkp(const char *p) { char t[512]; strncpy0(t, p, 512); for (char *s = t + 1; *s; s++) if (*s == '/') { *s = 0; z_mkdir(t); *s = '/'; } z_mkdir(t); }
static void lg(const char *f, ...) { if (logf_ < 0) return; char b[600]; va_list a; va_start(a, f); int n = vsnprintf(b, 600, f, a); va_end(a); z_write(logf_, b, MIN(n, 599)); }
static int begin(const char *kind) { if (cd < 0) { strcpy(msg, _("Elige un destino en otro disco")); return 0; } z_set_ro(D[cd].name, 0); u32 t[6]; z_time(t); snprintf(outdir, 300, "/%s/RESCATE-%u%02u%02u-%02u%02u", D[cd].name, t[5], t[4], t[3], t[2], t[1]); mkp(outdir); char l[320]; snprintf(l, 320, "%s/RESCATE.TXT", outdir); logf_ = z_open(l, O_WRITE | O_CREATE | O_APPEND); if (logf_ < 0) { snprintf(msg, 200, _("No se puede escribir en el destino: %s"), z_errstr(logf_)); return 0; } lg("ZunzunOS Rescate: %s, origen %s\n", kind, cs >= 0 ? S[cs].name : "?"); busy = 1; cancel = 0; sub[0] = 0; return 1; }
static void finish(const char *f) { lg("%s\n", f); z_close(logf_); logf_ = -1; z_sync(); busy = 0; pct = -1; strncpy0(msg, f, 200); char *cc = strstr(msg, " Carpeta "); sub[0] = 0; if (cc) { strncpy0(sub, cc + 1, 200); *cc = 0; } char m[240]; snprintf(m, 240, "[prueba] rescate: %s", f); z_log(m); }
static void clean(char *s) { for (; *s; s++) if (strchr(":*?\"<>|\\", *s) || (u8)*s < 32) *s = '_'; }
/* --- 1. copia tolerante --- */
static u64 cf, cb, ce, tb_; static char *CB;
static int wanted(const char *n) { if (cats == 1) return 1; const char *e = strrchr(n, '.'); if (!e) return 0; static const char *L[3] = {".doc.docx.odt.rtf.txt.pdf.xls.xlsx.ods.ppt.pptx.odp.csv.md.tex.epub.html.htm.pages.numbers.key.", ".jpg.jpeg.png.gif.bmp.tif.tiff.heic.raw.cr2.nef.arw.dng.webp.", ".mp3.wav.flac.ogg.m4a.aac.wma.mp4.mov.avi.mkv.wmv.webm.mpg.mpeg.3gp."}; char x[12]; int l = 0; for (const char *p = e; *p && l < 9; p++) x[l++] = tolower(*p); x[l] = '.'; x[l + 1] = 0; for (int i = 0; i < 3; i++) if (cats == 2 << i && strstr(L[i], x)) return 1; return 0; }
static void walk_size(const char *p, int depth) { zdirent d; if (depth > 40 || cancel) return; char *q = malloc(512); for (int i = 0; !z_readdir(p, i, &d); i++) { snprintf(q, 512, "%s/%s", p, d.name); if (d.is_dir) walk_size(q, depth + 1); else if (wanted(d.name)) { tb_ += d.size; cf++; } if (i % 64 == 0) { snprintf(msg, 200, _("Analizando: %lu archivos"), cf); tick(0); } } free(q); }
static void rescue_file(const char *a, const char *b, u64 size) {
    zdirent st; if (!z_stat(b, &st) && st.size == MIN(size, 0xFFFF0000UL)) { cb += size; cf++; return; } int f = z_open(a, O_READ); if (f < 0) { ce++; lg("NO LEIDO %s: %s\n", a, z_errstr(f)); return; } u64 pos = 0, bad = 0; int part = 0; char pn[540]; strncpy0(pn, b, 512); int g = z_open(pn, O_WRITE | O_CREATE | O_TRUNC); if (g < 0) { z_close(f); ce++; lg("NO CREADO %s: %s\n", b, z_errstr(g)); return; } u64 pw = 0;
    while (pos < size && !cancel) { long want = MIN(size - pos, 1UL << 20), r = z_read(f, CB, want); if (r <= 0) { long sk = MIN(size - pos, 4096UL); memset(CB, 0, sk); r = sk; bad += sk; z_seek(f, pos + sk, 0); } if (pw + r > 0xFFFF0000UL) { z_close(g); part++; snprintf(pn, 540, "%s.parte%d", b, part + 1); g = z_open(pn, O_WRITE | O_CREATE | O_TRUNC); pw = 0; if (g < 0) break; } long w = z_write(g, CB, r); if (w != r) { lg("ERROR ESCRIBIENDO %s: %s\n", pn, z_errstr(w < 0 ? (int)w : -28)); ce++; if (w == -28 || w >= 0) cancel = 2; break; } pos += r; pw += r; cb += r; P_(tb_ ? (cb >> 10) * 100 / MAX(1UL, tb_ >> 10) : 0, "%lu MB de %lu MB", cb >> 20, tb_ >> 20); }
    z_close(f); if (g >= 0) z_close(g); cf++; if (bad) { ce++; lg("DANADO %s: %lu bytes ilegibles\n", a, bad); }
}
static void copy_tree(const char *a, const char *b, int depth) { if (depth > 40 || cancel) return; mkp(b); int cnt = 0, cap = 256; zdirent d; typedef struct { char n[256]; u64 s; int dir; } e_t; e_t *v = malloc(cap * sizeof *v); while (!z_readdir(a, cnt, &d)) { if (cnt == cap) { cap *= 2; v = realloc(v, cap * sizeof *v); } strncpy0(v[cnt].n, d.name, 256); v[cnt].s = d.size; v[cnt].dir = d.is_dir; cnt++; } char *p = malloc(1200), *q = p + 600; for (int i = 0; i < cnt && !cancel; i++) { char c[256]; strcpy(c, v[i].n); clean(c); snprintf(p, 600, "%s/%s", a, v[i].n); snprintf(q, 600, "%s/%s", b, c); if (v[i].dir) copy_tree(p, q, depth + 1); else if (wanted(v[i].n)) { strncpy0(sub, v[i].n, 200); rescue_file(p, q, v[i].s); } } free(p); free(v); }
static void do_copy(void) { if (cs < 0 || !S[cs].mnt[0]) { strcpy(msg, _("Elige un volumen montado como origen")); return; } if (!begin("copia")) return; char a[300], b[320]; const char *rel = path_[0] == '/' ? path_ + 1 : path_; snprintf(a, 300, "/%s%s%s", S[cs].mnt, *rel ? "/" : "", rel); snprintf(b, 320, "%s/%s", outdir, S[cs].mnt); cf = cb = ce = tb_ = 0; walk_size(a, 0); u64 tot = cf; cf = 0; CB = malloc(1 << 20); copy_tree(a, b, 0); free(CB); char r[140]; snprintf(r, 140, _("%s %lu de %lu archivos, %lu MB, con problemas %lu. Carpeta %s"), cancel == 2 ? _("Destino lleno:") : cancel ? _("Cancelado:") : _("Terminado:"), cf, tot, cb >> 20, ce, outdir); sub[0] = 0; finish(r); }
/* --- lectura cruda con tolerancia --- */
static u8 *RW; static u64 rw_l, rw_n; static u32 rss; static const char *rdv; static u64 rlim, rbad; static int mapf = -1;
#define WS 2048
static int rw_fill(u64 l) { u32 n = MIN(rlim - l, (u64)WS); if (!n) return -1; int e = 0; if (!z_disk_read(rdv, l, n, RW)) { rw_l = l; rw_n = n; return 0; } for (u32 c = 0; c < n; ) { u32 st = MIN(n - c, 64U); if (!z_disk_read(rdv, l + c, st, RW + c * rss)) { c += st; continue; } for (u32 i = 0; i < st; i++, c++) if (z_disk_read(rdv, l + c, 1, RW + c * rss)) { memset(RW + c * rss, 0, rss); rbad++; if (mapf >= 0) { char m[40]; int k = snprintf(m, 40, "%lu\n", l + c); z_write(mapf, m, k); } if (cancel) { rw_l = l; rw_n = n; return 0; } tick(0); } } rw_l = l; rw_n = n; return e; }
static u8 *sec(u64 l) { if (l >= rlim) return 0; if (!rw_n || l < rw_l || l >= rw_l + rw_n) if (rw_fill(l)) return 0; return RW + (l - rw_l) * rss; }
static void raw_open(const char *d, u64 n, u32 ss) { rdv = d; rlim = n; rss = ss; rw_n = 0; rbad = 0; if (!RW) RW = malloc(WS * 4096); }
static inline int rb(u64 o) { u8 *p = sec(o / rss); return p ? p[o % rss] : -1; }
static u32 r32(u64 o) { return rb(o) | rb(o + 1) << 8 | rb(o + 2) << 16 | (u32)rb(o + 3) << 24; }
static u32 b32(u64 o) { return (u32)rb(o) << 24 | rb(o + 1) << 16 | rb(o + 2) << 8 | rb(o + 3); }
static u64 find(u64 o, const char *pat, int n, u64 lim) { u64 end = MIN(o + lim, rlim * rss); while (o + n <= end) { u64 l = o / rss; u8 *p = sec(l); if (!p) return 0; u32 i = o % rss; for (; i < rss; i++, o++) { if (p[i] != (u8)pat[0]) continue; if (i + n <= rss) { if (!memcmp(p + i, pat, n)) return o; } else { int k = 1; for (; k < n && rb(o + k) == (u8)pat[k]; k++); p = sec(l); if (k == n) return o; } } if (cancel) return 0; } return 0; }
/* --- 3. carving: devuelve longitud o 0 --- */
static u64 c_jpg(u64 o) { u64 p = o + 2; for (int g = 0; g < 4096; g++) { if (rb(p) != 0xFF) return 0; int m = rb(p + 1); if (m == 0xD9) return p + 2 - o; if (m == 0xDA) { u64 q = p + 2; for (;;) { q = find(q, "\xFF", 1, 64UL << 20); if (!q || q - o > (64UL << 20)) return 0; int k = rb(q + 1); if (k == 0xD9) return q + 2 - o; q += 1; } } if (m == 0xFF) { p++; continue; } if (m >= 0xD0 && m <= 0xD8) { p += 2; continue; } u32 l = rb(p + 2) << 8 | rb(p + 3); if (l < 2) return 0; p += 2 + l; } return 0; }
static u64 c_png(u64 o) { u64 p = o + 8; for (int i = 0; i < 200000; i++) { u32 l = b32(p); if (l > (64u << 20)) return 0; int t = rb(p + 4); if (!isalpha(t)) return 0; int e = rb(p + 4) == 'I' && rb(p + 5) == 'E' && rb(p + 6) == 'N' && rb(p + 7) == 'D'; p += 12UL + l; if (e) return p - o; if (p - o > (256UL << 20)) return 0; } return 0; }
static u64 skip_sub(u64 p) { for (;;) { int n = rb(p); if (n < 0) return 0; p++; if (!n) return p; p += n; } }
static u64 c_gif(u64 o) { int f = rb(o + 10); u64 p = o + 13 + (f & 0x80 ? 3UL << ((f & 7) + 1) : 0); for (int i = 0; i < 100000; i++) { int b = rb(p); if (b == 0x3B) return p + 1 - o; if (b == 0x21) { p = skip_sub(p + 2); if (!p) return 0; } else if (b == 0x2C) { int g = rb(p + 9); p += 10 + (g & 0x80 ? 3UL << ((g & 7) + 1) : 0) + 1; p = skip_sub(p); if (!p) return 0; } else return 0; } return 0; }
static u64 c_pdf(u64 o) { u64 last = 0, p = o + 5; for (int i = 0; i < 256; i++) { u64 q = find(p, "%%EOF", 5, last ? 256UL << 10 : 256UL << 20); if (!q) break; last = q + 5; p = last; } if (!last) return 0; for (int i = 0; i < 2; i++) { int c = rb(last); if (c == 13 || c == 10) last++; } return last - o; }
static u64 zip_end; static u64 c_zip(u64 o) { u64 q = find(o + 4, "PK\5\6", 4, 1UL << 30); if (!q) return 0; zip_end = q; return q + 22 + (rb(q + 20) | rb(q + 21) << 8) - o; }
static u64 c_rtf(u64 o) { int d = 0; for (u64 p = o, e = o + (32UL << 20); p < e; p++) { int c = rb(p); if (c < 0) return 0; if (c == '\\') p++; else if (c == '{') d++; else if (c == '}' && !--d) return p + 1 - o; if ((p & 0xFFFF) == 0 && cancel) return 0; } return 0; }
static u64 c_mp4(u64 o) { u64 p = o; int mv = 0; for (int i = 0; i < 4096; i++) { u64 s = b32(p); char t[5]; for (int k = 0; k < 4; k++) t[k] = rb(p + 4 + k); t[4] = 0; for (int k = 0; k < 4; k++) if (!(isalpha(t[k]) || isdigit(t[k]) || t[k] == ' ' || (u8)t[k] == 0xA9)) return mv ? p - o : 0; if (s == 1) s = (u64)b32(p + 8) << 32 | b32(p + 12); if (s < 8) return mv ? p - o : 0; if (!strcmp(t, "moov") || !strcmp(t, "mdat")) mv = 1; p += s; if ((p - o) > (8UL << 30)) return 0; } return mv ? p - o : 0; }
