static long nt_recover(del_t *d, int g) { u8 *r = malloc(N_rs); long w = -1; if (!nt_get(d->a, r)) { u8 *a = nt_at(r, 0x80, 1); if (a && !a[8]) { u32 l = *(u32 *)(a + 16); w = z_write(g, a + *(u16 *)(a + 20), l); } else if (a && !(*(u16 *)(a + 12) & 0xC001)) { u64 *mr; int n = nt_runs_(a + *(u16 *)(a + 32), a + *(u32 *)(a + 4), &mr); u64 left = d->size, v = 0; w = 0; u8 *z = calloc(1, N_cs); while (left && !cancel) { u64 c = nt_vmap(mr, n, v); u32 t = MIN(left, (u64)N_cs); if (c == ~0UL) z_write(g, z, t); else { for (u32 i = 0; i < t; i += rss) { u8 *q = sec((c * N_cs + i) / rss); if (!q) break; z_write(g, q, MIN(rss, t - i)); } } left -= t; w += t; v++; } free(z); free(mr); } } free(r); return w; }
static void do_recover(void) { int k = 0; for (int i = 0; i < ndl; i++) k += DL[i].sel; if (!k) { strcpy(msg, _("Marca algun archivo, o pulsa Todos")); return; } if (!begin("archivos borrados")) return; int done = 0; u64 total = 0; for (int i = 0; i < ndl && !cancel; i++) { del_t *d = &DL[i]; if (!d->sel) continue; char p[900], c[520]; strncpy0(c, d->path, 520); clean(c); snprintf(p, 900, "%s/BORRADOS%s", outdir, c); char dir[900]; strcpy(dir, p); char *sl = strrchr(dir, '/'); *sl = 0; mkp(dir); int g = z_open(p, O_WRITE | O_CREATE | O_TRUNC); if (g < 0) { lg("NO CREADO %s\n", p); continue; } if (d->ntfs == 2) { u64 *l = (u64 *)d->b, left = d->size; for (u64 x = 0; x < l[0] && left && !cancel; x++) { u64 o = l[1 + x * 2], n = MIN(l[2 + x * 2], left); for (u64 q = 0; q < n && !cancel; ) { u8 *s3 = sec((o + q) / rss); if (!s3) { left = 0; break; } u32 av = rss - (o + q) % rss, t = MIN(n - q, (u64)av); z_write(g, s3 + (o + q) % rss, t); q += t; } left -= n; } } else if (d->ntfs) nt_recover(d, g); else { u64 o = d->a, left = d->size; while (left && !cancel) { u8 *q = sec(o / rss); if (!q) break; u32 av = rss - o % rss, t = MIN(left, (u64)av); if (z_write(g, q + o % rss, t) != t) { cancel = 2; break; } o += t; left -= t; } } z_close(g); done++; total += d->size; lg("%s %lu bytes %s\n", d->path, d->size, d->ok ? "" : "(puede estar sobrescrito)"); P_(done * 100 / k, "%d de %d", done, k); } char r[120]; snprintf(r, 120, _("%s %d archivos, %lu MB. Carpeta %s"), cancel ? _("Interrumpido:") : _("Terminado:"), done, total >> 20, outdir); finish(r); }
