static void do_scan(void) { if (cs < 0 || !S[cs].disk) { strcpy(msg, _("Elige un disco completo")); return; } src_t *s = &S[cs]; raw_open(s->name, s->sectors, s->ss); busy = 1; cancel = 0; nlp = 0; u64 step = (1UL << 20) / s->ss; for (u64 l = 0; l < rlim && nlp < 64 && !cancel; l += l == 0 ? 63 : l == 63 ? step - 63 : step) { if ((l / step) % 64 == 0) P_(l * 100 / rlim, "Buscando... %lu MB", l * s->ss >> 20); u8 *b = sec(l); if (!b) break; lost_t e; memset(&e, 0, sizeof e); e.lba = l; if (b[510] == 0x55 && b[511] == 0xAA) { if (!memcmp(b + 3, "NTFS    ", 8)) { strcpy(e.kind, "NTFS"); e.n = *(u64 *)(b + 40) + 1; } else if (!memcmp(b + 3, "EXFAT   ", 8)) { strcpy(e.kind, "exFAT"); e.n = *(u64 *)(b + 72); } else if (!memcmp(b + 82, "FAT32   ", 8)) { strcpy(e.kind, "FAT32"); e.n = *(u32 *)(b + 32); memcpy(e.lab, b + 71, 11); } else if (!memcmp(b + 54, "FAT16   ", 8) || !memcmp(b + 54, "FAT12   ", 8)) { strcpy(e.kind, "FAT16"); e.n = *(u16 *)(b + 19); if (!e.n) e.n = *(u32 *)(b + 32); memcpy(e.lab, b + 43, 11); } } if (!e.kind[0] && l + 2 < rlim) { u8 *q = sec(l + 2); if (q && *(u16 *)(q + 56) == 0xEF53 && *(u32 *)(q + 4)) { strcpy(e.kind, "ext"); e.n = (u64)*(u32 *)(q + 4) * ((1024u << *(u32 *)(q + 24)) / 512); memcpy(e.lab, q + 120, 15); } } if (e.kind[0] && e.n && l + e.n <= rlim + 2) { if (l + e.n > rlim) e.n = rlim - l; LP[nlp++] = e; } } busy = 0; pct = -1; snprintf(msg, 200, _("%d sistemas de archivos encontrados"), nlp); char m[80]; snprintf(m, 80, "[prueba] particiones encontradas %d", nlp); z_log(m); }
